python3 << 'EOF'
import re

with open('/tmp/paper3_full_text.txt', 'r') as f:
    text = f.read()

print("="*70)
print("COMPREHENSIVE REDACTION VERIFICATION REPORT")
print("="*70)

# 1. Check for the specific GitHub URL mentioned
specific_github = "github.com/MrYxJ/calculate-flops"
if specific_github in text:
    print(f"\nCRITICAL: GitHub URL '{specific_github}' FOUND in document!")
else:
    print(f"\nPASS: GitHub URL '{specific_github}' NOT found in document")

# 2. Check for variations of GitHub
github_pattern = r'github\.com'
if re.search(github_pattern, text):
    print("WARNING: 'github.com' found in text")
    matches = re.finditer(github_pattern, text)
    for match in matches:
        start = max(0, match.start() - 50)
        end = min(len(text), match.end() + 50)
        print(f"  Context: ...{text[start:end]}...")
else:
    print("PASS: No 'github.com' references found")

# 3. Email addresses
email_pattern = r'\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b'
if re.search(email_pattern, text):
    print("\nWARNING: Email addresses found:")
    matches = re.findall(email_pattern, text)
    for match in matches:
        print(f"  {match}")
else:
    print("\nPASS: No email addresses found")

# 4. arXiv IDs
arxiv_pattern = r'(?:arXiv|arxiv)[\s:.]*(\d{4}\.\d{4,5})'
if re.search(arxiv_pattern, text):
    print("\nWARNING: arXiv IDs found:")
    matches = re.findall(arxiv_pattern, text)
    for match in matches:
        print(f"  {match}")
else:
    print("\nPASS: No arXiv IDs found")

# 5. Common names that might be authors
potential_names = re.findall(r'\b(?:Dr\.|Prof\.|Dr\.)\s+[A-Z][a-z]+(?:\s+[A-Z][a-z]+)?(?:\s+[A-Z][a-z]+)?\b', text)
if potential_names:
    print("\nWARNING: Potential author names (Dr., Prof.) found:")
    for name in set(potential_names):
        print(f"  {name}")
else:
    print("\nPASS: No obvious author names (Dr., Prof.) found")

# 6. Institution names - more specific
institutions = ['University', 'Institute', 'Laboratory', 'College', 'Corp', 'Inc', 'Ltd']
found_institutions = []
for inst in institutions:
    pattern = rf'\b(?:[A-Z][a-z]+\s+)*{inst}(?:\s+of\s+[A-Z][a-z]+)?'
    matches = re.findall(pattern, text)
    if matches:
        found_institutions.extend(matches)

if found_institutions:
    print("\nWARNING: Potential institution names found:")
    for inst in set(found_institutions):
        print(f"  {inst}")
else:
    print("\nPASS: No institution names found")

# 7. URLs in general
url_pattern = r'https?://[^\s]+'
if re.search(url_pattern, text):
    print("\nWARNING: URLs found:")
    matches = re.findall(url_pattern, text)
    for match in matches:
        print(f"  {match}")
else:
    print("\nPASS: No HTTP(S) URLs found")

# 8. Check for author/affiliation sections
if re.search(r'\bauthor\b|\baffiliation\b|\baffili\b', text, re.IGNORECASE):
    print("\nWARNING: Author/affiliation keywords found")
    matches = re.finditer(r'\bauthor\b|\baffiliation\b|\baffili\b', text, re.IGNORECASE)
    for match in matches:
        start = max(0, match.start() - 50)
        end = min(len(text), match.end() + 50)
        print(f"  Context: ...{text[start:end]}...")
else:
    print("\nPASS: No author/affiliation keywords found")

# 9. Check for acknowledgments section
if re.search(r'\backnowledge\b', text, re.IGNORECASE):
    print("\nWARNING: Acknowledgments section keyword found")
else:
    print("\nPASS: No acknowledgments section found")

# 10. Check for contact information
if re.search(r'\bcontact\b|\bemail\b', text, re.IGNORECASE):
    print("\nWARNING: Contact/email keywords found")
else:
    print("\nPASS: No contact information keywords found")

print("\n" + "="*70)
print("SUMMARY")
print("="*70)
print(f"Document text length: {len(text)} characters")
print(f"Number of lines: {len(text.splitlines())}")

EOF
